var modes = new AgentModeProvider(new AgentModeProviderOptions { DefaultMode = "plan" });
AIAgent agent = chatClient.AsAIAgent(new ChatClientAgentOptions
{
    AIContextProviders = [new TodoProvider(), modes],
});
AgentSession session = await agent.CreateSessionAsync();

// after the human approves the plan:
await modes.SetModeAsync(session, "execute");

// Harness: todo + mode are on by default; add a todo-driven loop
HarnessAgent h = chatClient.AsHarnessAgent(new HarnessAgentOptions
{
    LoopEvaluators = [new TodoCompletionLoopEvaluator(
        new TodoCompletionLoopEvaluatorOptions { Modes = ["execute"] })],
    LoopAgentOptions = new LoopAgentOptions { MaxIterations = 10 },
});
